<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Throwable;
use OpenApi\Attributes as OA;
use DateTime;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageFilter;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageCursor;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageAttributes;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Notification\Message\Application\Usecase\List\MessageListUsecase;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class MessageListController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly MessageListUsecase $listUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/template/template",
        tags: ["Message"],
        description:"Create",
        responses: [
        new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/MessageApiListDTO")),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List Message");
        $span = $this->startSpan("List Message");
        try {
            $params = $request->getQueryParams();
            $filter = new MessageFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                tenant: isset($params['tenant']) ? new TenantRef($params['tenant']) : null,
                tenants: isset($params['tenants']) ? explode(",", $params['tenants']) : null,
            );
            $cursor = new MessageCursor(
                limit: (int)($params['limit'] ?? 100),
                sinceUid: $params['since-uid'] ?? null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (MessageAttributes $item): MessageApiDTO => $this->mapMessage($request, $item), $result->values())];
            $nextLink = $this->nextLink($result->cursor(), $params);
            if (null !== $nextLink) {
                $value['next'] = "?{$nextLink}";
            }
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function nextLink(?MessageCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for Message");
        $span = $this->startSpan("Generic allow for Message");
        try {
            if (!$value) {
                return null;
            }
            $link = [];
            if (isset($params['limit'])) {
                $link['limit'] = 'limit=' . $params['limit'];
            }
            $sinceUid = $value->sinceUid();
            if (null !== $sinceUid) {
                $link['since-uid'] = 'since-uid=' . urlencode($sinceUid);
            }
            return implode('&', $link);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapMessage(ServerRequestInterface $request, MessageAttributes $value): MessageApiDTO
    {
        $this->logDebug("Map entity to output dto for Message");
        $span = $this->startSpan("Map entity to output dto for Message");
        try {
            $tenant = $value->getTenant();
            $dto = new MessageApiDTO();
            $dto->uid = $value->getUid();
            $dto->target = $value->getTarget();
            $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
            $dto->urgent = $value->isUrgent();
            $dto->content = $value->getContent();
            $dto->retries = $value->getRetries();
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->sendAt = $value->getSendAt()?->format(DateTime::ATOM);
            $dto->lockAt = $value->getLockAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
